full=sum(1<<i for i in range(len(cell_id)))
base_shapes=[]
for (h,w),cnt,name in piece_info:
    places=[]
    for r in range(0,8-h):
      for c in range(0,21-w):
        cells={(rr,cc) for rr in range(r,r+h) for cc in range(c,c+w)}
        if cells<=mask:
          bits=sum(1<<cell_id[p] for p in cells)
