initial_counts=tuple(x[1] for x in piece_info)
# order choices small; record up to 20 tilings
nodes=0; sols=[]
@functools.lru_cache(maxsize=None)
def search(covered, counts):
    global nodes
    nodes+=1
    if covered==full:
        return ((),) if all(x==0 for x in counts) else ()
    # reject if remaining area mismatch
    rem_area=sum(cnt*piece_info[i][0][0]*piece_info[i][0][1] for i,cnt in enumerate(counts))
    rem_mask=full ^ covered
    if rem_area != rem_mask.bit_count(): return ()
    best=None; opts_best=None
    bits_avail=rem_mask
    while bits_avail:
        low=bits_avail & -bits_avail; idx=low.bit_length()-1; bits_avail-=low
        opts=[]
        for ti,bits,pos in placements_by_cell[idx]:
            if counts[ti] and (bits & covered)==0:
                opts.append((ti,bits,pos))
        if best is None or len(opts)<len(opts_best):
            best=idx; opts_best=opts
            if len(opts)==0: return ()
            if len(opts)==1: break
    ret=[]
    for ti,bits,pos in opts_best:
        cc=list(counts); cc[ti]-=1
        for tail in search(covered|bits,tuple(cc)):
            ret.append(((ti,pos),)+tail)
            if len(ret)>=20: return tuple(ret)
    return tuple(ret)
solutions=search(0,initial_counts)
